#include <iostream>
using namespace std;
int main() {
    int x = 10;
    int *p = &x;        // p 存 x 的地址
    cout << *p << endl; // 10：顺着地址取值
    *p = 20;            // 改 *p 就是改 x
    cout << x << endl;  // 20
    return 0;
}

#include <iostream>
using namespace std;
int a[105][105];
int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> a[i][j];
    for (int i = 0; i < n; i++) {   // 每行求和
        int s = 0;
        for (int j = 0; j < m; j++) s += a[i][j];
        cout << s << endl;
    }
    return 0;
}

