#include <iostream>
using namespace std;
void f1(int x) { x = 100; }      // 值传递：外面不变
void f2(int &x) { x = 100; }     // 引用传递：外面变 100
void f3(int *x) { *x = 100; }    // 指针传递：外面也变
int main() {
    int a = 1, b = 1, c = 1;
    f1(a); f2(b); f3(&c);
    cout << a << " " << b << " " << c << endl; // 1 100 100
    return 0;
}

#include <iostream>
using namespace std;
int f[50];
int main() {
    int n;
    cin >> n;
    f[1] = 1; f[2] = 1;              // 初始值
    for (int i = 3; i <= n; i++)
        f[i] = f[i - 1] + f[i - 2];  // 递推关系式
    cout << f[n] << endl;             // 第 n 项
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int n, a[105];
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n - 1; i++)            // 冒泡排序
        for (int j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) swap(a[j], a[j + 1]);
    for (int i = 0; i < n; i++) cout << a[i] << " ";
    cout << endl;
    return 0;
}

